// WorkItem 我的工作事项（词汇表「我的工作事项」）；卡片派生事实，动作在任务详情抽屉完成
type WorkItem struct {
	// ActionLabel 卡片文字按钮文案（我的工作 PRD §5.3、AC-55；派生字段）：本人要办的三组为「去处理」；等待他人与卡点只读、不派生文字按钮（空串，点条目行打开抽屉，#168）
	ActionLabel string `json:"actionLabel"`

	// CanRemind 卡片能否直接一键提醒当前待行动人（MW-13；派生字段）；按 refKey 指向的提醒目标寻址，不提醒本人、访客不可，提醒频次上限为同一人对同一任务每天 1 次
	CanRemind bool `json:"canRemind"`

	// DrawerTab 建议打开的任务详情 Tab（overview/audit/discussion）
	DrawerTab *string `json:"drawerTab,omitempty"`

	// DueDate 任务截止或输入期望时间
	DueDate *openapi_types.Date `json:"dueDate,omitempty"`

	// Kind 事项类型（task/field_change/intermediate_review/final_review/input_request/invite/upstream/blocker 等）
	Kind string `json:"kind"`

	// Overdue 超期标红（模块 PRD §5.4）
	Overdue *bool `json:"overdue,omitempty"`

	// RefId 事项自身 ID（审批单／输入请求／邀请）
	RefId *int64 `json:"refId,omitempty"`

	// RefKey 提醒目标的合成键；一键提醒按此寻址（卡点组为本条卡点的键，等待他人组为该等待事项自身的 wait:<事项类型>:<事项 ID>）
	RefKey *string `json:"refKey,omitempty"`

	// RejectedReason 被退回事项的「已退回：理由」
	RejectedReason *string `json:"rejectedReason,omitempty"`

	// Stage 当前环节（等待他人卡片显示停在谁手里）
	Stage    *string `json:"stage,omitempty"`
	TaskId   *int64  `json:"taskId,omitempty"`
	TaskName *string `json:"taskName,omitempty"`
	Title    string  `json:"title"`

	// UnreadyNote 「上游未就绪：缺 XX」标记
	UnreadyNote *string `json:"unreadyNote,omitempty"`

	// WaitingDays 审批件与输入请求的已等待天数（排序事实；模块 PRD §5.2 规定卡片不显示，仅供排序与详情使用）
	WaitingDays *int `json:"waitingDays,omitempty"`
}

